insert into events(title,description,city,location,start_date,end_date,category,source_url,confidence,status,source,confidence_score,needs_review,ingestion_status) select 'Lathrop Ki Diwali 2026','Mitra USA links this Lathrop Diwali celebration and performer registration from its official homepage. November 14, 2026, 6 PM Pacific at Mossdale Elementary School. The organizer-linked page gives 10 PM as the finish while its flyer says 9:30 PM, so the end time remains unconfirmed. The form offers free solo/group performance participation; confirm general visitor access, registration and any separate activity costs with the organizer. Checked November 6, 2026. No poster or photos reused.','Lathrop','Mossdale Elementary School, 455 Brookhurst Boulevard, Lathrop','2026-11-14T18:00:00-08:00'::timestamptz,null::timestamptz,'Seasonal celebrations','https://www.zeffy.com/en-US/ticketing/lathrop-ki-diwali-2026-registration-mitra-usa','HIGH','approved','editorial_seasonal_2026',0.95,false,'approved' where not exists(select 1 from events where city='Lathrop' and source_url='https://www.zeffy.com/en-US/ticketing/lathrop-ki-diwali-2026-registration-mitra-usa' and start_date='2026-11-14T18:00:00-08:00'::timestamptz);
insert into events(title,description,city,location,start_date,end_date,category,source_url,confidence,status,source,confidence_score,needs_review,ingestion_status) select 'Karthika Masa Deeksha Mahotsavam 2026','Sri Veda Gayatri Temple lists the start of its Karthika Masa Deeksha Mahotsavam for November 9, 2026 at 8 AM at the temple, 702 W Yosemite Avenue. The organizer describes pujas and devotional activities and provides registration and sponsorship information. Confirm individual program times, duration, participation and costs directly; no end time or full-month schedule established. The Lathrop mailing address is not the event venue. Primary page checked November 6, 2026; no flyer or photos reused.','Manteca','Sri Veda Gayatri Temple, 702 W Yosemite Avenue, Manteca','2026-11-09T08:00:00-08:00'::timestamptz,null::timestamptz,'Cultural & religious events','https://www.srivedagayatritemple.org/events/cmvwsf2fs000004ib5wdg5lsd/register','HIGH','approved','editorial_community_2026',0.95,false,'approved' where not exists(select 1 from events where city='Manteca' and source_url='https://www.srivedagayatritemple.org/events/cmvwsf2fs000004ib5wdg5lsd/register' and start_date='2026-11-09T08:00:00-08:00'::timestamptz);
insert into events(title,description,city,location,start_date,end_date,category,source_url,confidence,status,source,confidence_score,needs_review,ingestion_status) select 'MH Shala AI Builders — Student Hackathon','Aapli Marathi Shala community initiative: an in-person AI app-building day for students ages 13+, November 21, 2026, 9 AM–3 PM at Delta College Mountain House. Individuals or teams of up to four may participate. The detailed notice links free registration and requires parent or guardian permission and applicable tool age limits. Confirm registration, available places, classroom and current rules with the organizer; the page also has a generic no-registration footer, so walk-in access is not promised. Checked November 6, 2026; no event artwork reused.','Mountain House','Delta College Mountain House Campus, 2073 Central Parkway','2026-11-21T09:00:00-08:00'::timestamptz,'2026-11-21T15:00:00-08:00'::timestamptz,'Education & community','https://mhshala.org/events/mh-shala-ai-builders/','HIGH','approved','editorial_community_2026',0.95,false,'approved' where not exists(select 1 from events where city='Mountain House' and source_url='https://mhshala.org/events/mh-shala-ai-builders/' and start_date='2026-11-21T09:00:00-08:00'::timestamptz);
